<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jvmFlag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;-javaagent:/dd-agent/dd-java-agent-\${dd.agent.version}.jar&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jvmFlag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
